    "This code runs inside your Discord with full access to your account. Only continue if you understand what it does.": "Этот код выполняется внутри Discord с полным доступом к вашему аккаунту. Продолжайте, только если понимаете, что он делает.",
    "The address has to start with https://": "Адрес должен начинаться с https://",
    "Please do not private message Endcord plugin developers for support!": "Пожалуйста, не пишите разработчикам плагинов Endcord в личку за поддержкой!",
    "Instead, use the Endcord support channel:": "Вместо этого используйте канал поддержки Endcord:",
    "Discord Desktop": "Discord для ПК",
    "Dismiss Notification": "Закрыть уведомление",
