    "Allow newlines in command inputs (CTRL + Shift + Enter)": "Разрешить переносы строк в командах (CTRL + Shift + Enter)",
    "Allow rendering GIFs": "Разрешить показ GIF",
    "Allow selected users to bypass status outside of DMs too (acts like a channel/guild bypass, but it's for all messages sent by the selected users)": "Выбранные пользователи обходят статус и вне ЛС (как обход канала/сервера, но для всех их сообщений)",
