    "Also download non-media attachments. Only enable this if you trust what people send you.": "Скачивать и не-медиа вложения. Включайте, только если доверяете отправителям.",
    "Also export channels you cannot view, including their permission overwrites. Requires a plugin that reveals hidden channels (e.g. ShowHiddenChannels), otherwise the channel data may be obfuscated.": "Экспортировать и недоступные каналы с их правами. Нужен плагин, показывающий скрытые каналы (например ShowHiddenChannels), иначе данные могут быть неполными.",
    "Also flag people who show a camera icon but never send video. Can misfire if you have incoming video turned off or a very slow connection.": "Отмечать и тех, у кого значок камеры, но нет видео. Может ошибаться при выключенном входящем видео или медленной сети.",
    "Also highlight URLs in embed content.": "Подсвечивать ссылки и во встроенном содержимом.",
    "Also leave when the followed user leaves": "Выходить, когда уходит тот, за кем следите",
