    "Discord is known to punish users of scripts or plugins that modify the completion of Quests. Modifying the completion of Quests is against Discord's": "Известно, что Discord наказывает за скрипты и плагины, меняющие выполнение заданий. Это нарушает",
    "Terms of Service": "Условия использования",
    "The punishment consists of a temporary or permanent loss of access to Quests and their rewards.": "Наказание — временная или постоянная потеря доступа к заданиям и наградам.",
    "The punishment also consists of an account standing violation which lasts 2 years per violation.": "Также за каждое нарушение статус аккаунта ухудшается на 2 года.",
