    "The punishment appears limited to loss of access to Quests and their rewards, but Discord may escalate at any time.": "Пока наказание ограничивается потерей доступа к заданиям и наградам, но Discord может ужесточить его в любой момент.",
    "Due to the various methods Discord uses to track users, there's no way to realistically evade detection. If you proceed, understand that Discord likely will detect it at some point.": "Из-за множества способов отслеживания избежать обнаружения практически невозможно. Если продолжите, Discord, скорее всего, рано или поздно это заметит.",
    "Discord has begun punishing users of scripts and plugins that modify the completion of Quests. Modifying the completion of Quests is against their": "Discord начал наказывать за скрипты и плагины, меняющие выполнение заданий. Это нарушает",
